import json, sys, random
sys.path.insert(0,'/workspace/tests'); sys.path.insert(0,'/workspace/submission')
from harness import prof, query, rec
import main as m
LABELS = ['x','y','z','w','q']
ORIGINS = ['.','test.','a.test.','sub.test.','deep.sub.test.','z.a.test.','ex.test.']
TARGETS = ['end.test.','z.sub.test.','out.example.','a.test.','test.','sub.test.']
for trial in range(300):
    rng = random.Random(trial*9773+7)
    origins = rng.sample(sorted(set(ORIGINS)), rng.randint(0,4))
    zones=[]; reasons={}
    for origin in origins:
        recs=[]; owner_type={}
        for _ in range(rng.randint(0,5)):
            if origin=='.' and rng.random()<0.2: owner='*.'
            elif rng.random()<0.15: owner='*.'+origin
            else:
                chain='.'.join(rng.choice(LABELS) for _ in range(rng.randint(1,3)))
                owner=chain+'.'+origin
            if owner==origin or owner in owner_type: continue
            if rng.random()<0.3:
                owner_type[owner]='CNAME'; recs.append(rec(owner,'CNAME',rng.choice(TARGETS)))
            else:
                rtype=rng.choice(['A','AAAA','TXT']); owner_type[owner]=rtype
                for _ in range(rng.randint(1,2)):
                    if rtype=='A': recs.append(rec(owner,'A','192.0.2.%d'%rng.randint(0,255)))
                    elif rtype=='AAAA': recs.append(rec(owner,'AAAA','2001:db8::%x'%rng.randint(0,255)))
                    else: recs.append(rec(owner,'TXT',rng.choice(['hi','v2','A'])))
        zones.append({'origin':origin,'records':recs})
    doc={'zones':zones,'profiles':[prof('p')],'queries':[],'observations':[]}
    try:
        m.analyze(doc)
    except m.Invalid as e:
        if not reasons:
            print('trial',trial,'reason:',e)
            print(json.dumps(doc)[:500])
        reasons[str(e)]=reasons.get(str(e),0)+1
from collections import Counter
print(Counter(reasons))
PYEOF
